return "    .afklevel_slot {\n        sid 0 : integer # 学员id\n        cd 1 : integer # 冷却时间\n    }\n    get_afklevel_data 5800 {\n        response {\n            lv 0 : integer # 等级\n            slots 1 : *afklevel_slot\n            wait_trans 2 : integer # 1 等待转换\n            use_servant 3 : *integer\n        }\n    }\n\n    afklevel_servant_up 5801 {\n        request {\n            idx 0 : integer # 栏位索引\n            servantid 1 : integer # 学员id\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败, 栏位未解锁 3 失败, 栏位已有学员 4 失败, 学员不存在 5 失败, 栏位冷却中 6 失败, 学员已在其他栏位\n            slot 1 : afklevel_slot\n        }\n    }\n\n    afklevel_servant_down 5802 {\n        request {\n            idx 0 : integer # 栏位索引\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败, 栏位未解锁 3 失败, 栏位无学员 4 失败，钻石不足 5 学员正在驻守中\n            slot 1 : afklevel_slot\n            cost_diamond 2 : integer\n        }\n    }\n\n    afklevel_unlock_slot 5803 {\n        response {\n            result 0 : integer # 1 成功 2 失败，全部栏位已解锁 3 失败，钻石不足\n            slots 1 : *afklevel_slot\n            cost_diamond 2 : integer\n        }\n    }\n\n    afklevel_levelup 5804 {\n        response {\n            result 0 : integer # 1 成功 2 失败，当前不能升级 3 失败，已达最大等级 4 失败，材料不足 5 失败，受共振点限制\n            consumes 1 : *consumeids\n            lv 2 : integer\n            strengthpoint 3 : integer\n        }\n    }\n\n    afklevel_clear_cd 5805 {\n        request {\n            idx 0 : integer # 栏位索引\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败，栏位未解锁 3 失败，栏位无冷却 4 失败，钻石不足\n            slot 1 : afklevel_slot\n            cost_diamond 2 : integer\n        }\n    }\n\n    afklevel_trans 5806 {\n        response {\n            result 0 : integer # 1 成功 2 失败，当前不能转换\n            slots 1 : *afklevel_slot\n        }\n    }\n\n    afklevel_choose 5807 {\n        request {\n            servantids 1 : *integer # 学员id\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败，参数错误 3 失败，参数中存在一样的servant 4 失败，有学员在下面列表中\n            lv     1 : integer # 等级\n            slots  2 : *afklevel_slot\n            wait_trans  3 : integer # 1 等待转换\n            use_servant 4 : *integer\n        }\n    }\n"
